class Solution:
    def countHillValley(self, nums: List[int]) -> int:
        result, inc = 0, -1
        for i in range(len(nums)-1):
            if nums[i] < nums[i+1]:
                result += int(inc == 0)
                inc = 1
            elif nums[i] > nums[i+1]:
                result += int(inc == 1)
                inc = 0
        return result

